#define H_NCOUNT (H_VCOUNT * H_TCOUNT)
#define H_SCOUNT (H_LCOUNT * H_NCOUNT)

static inline const uni_rec* uni_rec_of(uint32_t cp) {
    if (cp >= 0x110000) cp = 0xFFFD;
    return &uni_recs[uni_stage2[((uint32_t)uni_stage1[cp >> UNI_BLOCK_SHIFT] << UNI_BLOCK_SHIFT) | (cp & UNI_BLOCK_MASK)]];
}
static inline int uni_incb(const uni_rec* r) { return (r->flags >> F_INCB_SHIFT) & 3; }

/* ── UTF-8 ─────────────────────────────────────────────────────────────── */

/* Decode one code point at s[*i] (i < n); advances *i. */
static inline uint32_t u8_next(const unsigned char* s, size_t n, size_t* i) {
    size_t k = *i;
    unsigned c = s[k];
    if (c < 0x80) { *i = k + 1; return c; }
    if (c >= 0xC2 && c <= 0xDF) {
        if (k + 1 < n && (s[k + 1] & 0xC0) == 0x80) { *i = k + 2; return ((c & 0x1F) << 6) | (s[k + 1] & 0x3F); }
    } else if (c >= 0xE0 && c <= 0xEF) {
        unsigned lo = (c == 0xE0) ? 0xA0 : 0x80, hi = (c == 0xED) ? 0x9F : 0xBF;
        if (k + 1 < n && s[k + 1] >= lo && s[k + 1] <= hi) {
            if (k + 2 < n && (s[k + 2] & 0xC0) == 0x80) {
                *i = k + 3; return ((c & 0x0F) << 12) | ((s[k + 1] & 0x3Fu) << 6) | (s[k + 2] & 0x3F);
            }
            *i = k + 2; return 0xFFFD;
        }
    } else if (c >= 0xF0 && c <= 0xF4) {
        unsigned lo = (c == 0xF0) ? 0x90 : 0x80, hi = (c == 0xF4) ? 0x8F : 0xBF;
        if (k + 1 < n && s[k + 1] >= lo && s[k + 1] <= hi) {
            if (k + 2 < n && (s[k + 2] & 0xC0) == 0x80) {
                if (k + 3 < n && (s[k + 3] & 0xC0) == 0x80) {
                    *i = k + 4;
                    return ((c & 0x07u) << 18) | ((s[k + 1] & 0x3Fu) << 12) | ((s[k + 2] & 0x3Fu) << 6) | (s[k + 3] & 0x3F);
                }
                *i = k + 3; return 0xFFFD;
            }
            *i = k + 2; return 0xFFFD;
        }
    }
    *i = k + 1;
    return 0xFFFD;
}

static inline int u8_len(uint32_t cp) { return cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4; }

static inline unsigned char* u8_put(unsigned char* q, uint32_t cp) {
    if (cp < 0x80) { *q++ = (unsigned char)cp; }
    else if (cp < 0x800) { *q++ = (unsigned char)(0xC0 | (cp >> 6)); *q++ = (unsigned char)(0x80 | (cp & 0x3F)); }
    else if (cp < 0x10000) {
        *q++ = (unsigned char)(0xE0 | (cp >> 12)); *q++ = (unsigned char)(0x80 | ((cp >> 6) & 0x3F));
        *q++ = (unsigned char)(0x80 | (cp & 0x3F));
    } else {
        *q++ = (unsigned char)(0xF0 | (cp >> 18)); *q++ = (unsigned char)(0x80 | ((cp >> 12) & 0x3F));
        *q++ = (unsigned char)(0x80 | ((cp >> 6) & 0x3F)); *q++ = (unsigned char)(0x80 | (cp & 0x3F));
    }
    return q;
}

/* ── Growable buffers ──────────────────────────────────────────────────── */

typedef struct { uint32_t* v; size_t n, cap; int oom; } cpbuf;

static int cp_reserve(cpbuf* b, size_t extra) {
    if (b->oom) return 0;
    if (b->n + extra <= b->cap) return 1;
    size_t nc = b->cap ? b->cap * 2 : 64;
    while (nc < b->n + extra) nc *= 2;
    uint32_t* nv = (uint32_t*)realloc(b->v, nc * sizeof(uint32_t));
    if (!nv) { b->oom = 1; return 0; }
    b->v = nv; b->cap = nc;
    return 1;
}
static inline void cp_push(cpbuf* b, uint32_t c) {
    if (b->n < b->cap || cp_reserve(b, 1)) b->v[b->n++] = c;
}

/* Opaque result handed to Tauraro: bytes (len) or int64 pairs (count). */
typedef struct { size_t len; unsigned char* bytes; int64_t* pairs; size_t count; } uni_result;

static uni_result* res_bytes_from_cps(const cpbuf* b) {
    size_t i, len = 0;
    uni_result* r;
    unsigned char* q;
    if (b->oom) return NULL;
    for (i = 0; i < b->n; i++) len += (size_t)u8_len(b->v[i]);
    r = (uni_result*)calloc(1, sizeof *r);
    if (!r) return NULL;
    r->bytes = (unsigned char*)malloc(len + 1);
    if (!r->bytes) { free(r); return NULL; }
    q = r->bytes;
    for (i = 0; i < b->n; i++) q = u8_put(q, b->v[i]);
    r->len = len;
    return r;
}

static void decode_all(const unsigned char* s, size_t n, cpbuf* out) {
    size_t i = 0;
    cp_reserve(out, n + 1);
    while (i < n && !out->oom) cp_push(out, u8_next(s, n, &i));
}

/* ── Lookups ───────────────────────────────────────────────────────────── */

static const uni_dec* find_dec(uint32_t cp) {
    size_t lo = 0, hi = sizeof uni_decs / sizeof uni_decs[0];
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (uni_decs[mid].cp < cp) lo = mid + 1;
        else if (uni_decs[mid].cp > cp) hi = mid;
        else return &uni_decs[mid];
    }
    return NULL;
}

static uint32_t compose_pair(uint32_t a, uint32_t b) {
    /* Hangul L+V and LV+T are algorithmic. */
    if (a >= H_LBASE && a < H_LBASE + H_LCOUNT && b >= H_VBASE && b < H_VBASE + H_VCOUNT)
        return H_SBASE + ((a - H_LBASE) * H_VCOUNT + (b - H_VBASE)) * H_TCOUNT;
    if (a >= H_SBASE && a < H_SBASE + H_SCOUNT && (a - H_SBASE) % H_TCOUNT == 0 &&
        b > H_TBASE && b < H_TBASE + H_TCOUNT)
        return a + (b - H_TBASE);
    {
        size_t lo = 0, hi = sizeof uni_comps / sizeof uni_comps[0];
        while (lo < hi) {
            size_t mid = (lo + hi) / 2;
            const uni_comp* e = &uni_comps[mid];
            if (e->a < a || (e->a == a && e->b < b)) lo = mid + 1;
            else if (e->a == a && e->b == b) return e->c;
            else hi = mid;
        }
    }
    return 0;
}

static const uni_case* find_case(const uni_case* t, size_t cnt, uint32_t cp) {
    size_t lo = 0, hi = cnt;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (t[mid].cp < cp) lo = mid + 1;
        else if (t[mid].cp > cp) hi = mid;
        else return &t[mid];
    }
    return NULL;
}
#define CASE_TABLE(nm) uni_##nm, (sizeof uni_##nm / sizeof uni_##nm[0])

/* Append the full mapping of cp from a case table. */
static void case_push(cpbuf* out, const uni_case* t, size_t cnt, uint32_t cp) {
    const uni_case* e = find_case(t, cnt, cp);
    if (!e) { cp_push(out, cp); return; }
    if (e->n == 0) { cp_push(out, e->v); return; }
    { uint32_t k; for (k = 0; k < e->n; k++) cp_push(out, uni_case_data[e->v + k]); }
}

static uint32_t case_simple(const uni_case* t, size_t cnt, uint32_t cp) {
    const uni_case* e = find_case(t, cnt, cp);
    return e ? e->simple : cp;
}

/* ── Normalization ─────────────────────────────────────────────────────── */

enum { FORM_NFC = 0, FORM_NFD = 1, FORM_NFKC = 2, FORM_NFKD = 3 };

/* Quick check (UAX #15 §9): 0 = yes, 1 = no, 2 = maybe. */
static int quick_check(int form, const unsigned char* s, size_t n) {
    size_t i = 0;
    unsigned last_ccc = 0;
    int result = 0;
    unsigned no_mask, maybe_mask;
    switch (form) {
        case FORM_NFC: no_mask = F_NFC_NO; maybe_mask = F_NFC_MAYBE; break;
        case FORM_NFD: no_mask = F_NFD_NO; maybe_mask = 0; break;
        case FORM_NFKC: no_mask = F_NFKC_NO; maybe_mask = F_NFKC_MAYBE; break;
        default: no_mask = F_NFKD_NO; maybe_mask = 0; break;
    }
    while (i < n) {
        if (s[i] < 0x80) { i++; last_ccc = 0; continue; }
        {
            size_t at = i;
            uint32_t cp = u8_next(s, n, &i);
            const uni_rec* r;
            if (cp == 0xFFFD && !(i - at == 3 && s[at] == 0xEF && s[at + 1] == 0xBF && s[at + 2] == 0xBD))
                return 1;    /* ill-formed input is never "normalized" text */
            r = uni_rec_of(cp);
            if (r->ccc != 0 && last_ccc > r->ccc) return 1;
            if (r->flags & no_mask) return 1;
            if (r->flags & maybe_mask) result = 2;
            last_ccc = r->ccc;
        }
    }
    return result;
}

static void decompose_cp(cpbuf* out, uint32_t cp, int compat) {
    if (cp >= H_SBASE && cp < H_SBASE + H_SCOUNT) {
        uint32_t si = cp - H_SBASE;
        cp_push(out, H_LBASE + si / H_NCOUNT);
        cp_push(out, H_VBASE + (si % H_NCOUNT) / H_TCOUNT);
        if (si % H_TCOUNT) cp_push(out, H_TBASE + si % H_TCOUNT);
        return;
    }
    if (cp >= 0x80 && (uni_rec_of(cp)->flags & F_HAS_DECOMP)) {
        const uni_dec* d = find_dec(cp);
        if (d) {
            unsigned off = compat ? d->koff : d->coff, len = compat ? d->klen : d->clen;
            if (len) {
                unsigned k;
                if (!cp_reserve(out, len)) return;
                for (k = 0; k < len; k++) out->v[out->n++] = uni_dec_data[off + k];
                return;
            }
        }
    }
    cp_push(out, cp);
}

static inline unsigned ccc_of(uint32_t cp) { return cp < 0x300 ? 0 : uni_rec_of(cp)->ccc; }

/* Canonical ordering: stable sort of each run of non-starters by ccc. */
static void canonical_order(cpbuf* b) {
    size_t i = 0, n = b->n;
    uint32_t* v = b->v;
    while (i < n) {
        size_t j;
        if (ccc_of(v[i]) == 0) { i++; continue; }
        j = i;
        while (j < n && ccc_of(v[j]) != 0) j++;
        if (j - i > 1) {     /* insertion sort: runs are short */
            size_t a;
            for (a = i + 1; a < j; a++) {
                uint32_t x = v[a]; unsigned cx = ccc_of(x); size_t k = a;
                while (k > i && ccc_of(v[k - 1]) > cx) { v[k] = v[k - 1]; k--; }
                v[k] = x;
            }
        }
        i = j;
    }
}

static void canonical_compose(cpbuf* b) {
    size_t i, j = 0, n = b->n;
    long starter = -1;
    uint32_t* v = b->v;
    for (i = 0; i < n; i++) {
        uint32_t c = v[i];
        const uni_rec* r = uni_rec_of(c);
        unsigned cc = r->ccc;
        if (starter >= 0 && (r->flags & F_NFC_MAYBE)) {
            int unblocked;
            if ((long)j - 1 == starter) unblocked = 1;
            else { unsigned pc = ccc_of(v[j - 1]); unblocked = pc != 0 && pc < cc; }
            if (unblocked) {
                uint32_t comp = compose_pair(v[starter], c);
                if (comp) { v[starter] = comp; continue; }
            }
        }
        if (cc == 0) starter = (long)j;
        v[j++] = c;
    }
    b->n = j;
}

static uni_result* normalize(int form, const unsigned char* s, size_t n) {
    cpbuf b = {0};
    size_t i = 0;
    int compat = (form == FORM_NFKC || form == FORM_NFKD);
    uni_result* r;
    cp_reserve(&b, n + 16);
    while (i < n && !b.oom) {
        uint32_t cp = u8_next(s, n, &i);
        decompose_cp(&b, cp, compat);
    }
    if (!b.oom) {
        canonical_order(&b);
        if (form == FORM_NFC || form == FORM_NFKC) canonical_compose(&b);
    }
    r = res_bytes_from_cps(&b);
    free(b.v);
    return r;
}

/* ── Case mapping ──────────────────────────────────────────────────────── */

enum { OP_LOWER = 4, OP_UPPER = 5, OP_FOLD = 6, OP_TITLE = 7 };

static int is_cased(uint32_t c) { return (uni_rec_of(c)->flags & F_CASED) != 0; }
static int is_case_ign(uint32_t c) { return (uni_rec_of(c)->flags & F_CASE_IGN) != 0; }

/* Final_Sigma (Unicode §3.13, Table 3-17) for the sigma at index i. */
static int final_sigma(const uint32_t* v, size_t n, size_t i) {
    size_t k = i;
    int before = 0, after = 0;
    while (k > 0) {
        k--;
        if (is_case_ign(v[k])) continue;
        before = is_cased(v[k]);
        break;
    }
    if (!before) return 0;
    for (k = i + 1; k < n; k++) {
        if (is_case_ign(v[k])) continue;
        after = is_cased(v[k]);
        break;
    }
    return !after;
}

static void word_breaks(const uint32_t* v, size_t n, unsigned char* brk);
static int is_wordlike(uint32_t c);

static uni_result* case_map(int op, const unsigned char* s, size_t n) {
    cpbuf in = {0}, out = {0};
    size_t i;
    uni_result* r;
    unsigned char* brk = NULL;
    decode_all(s, n, &in);
    cp_reserve(&out, in.n + in.n / 8 + 16);
    if (op == OP_TITLE && !in.oom) {
        brk = (unsigned char*)calloc(in.n + 1, 1);
        if (!brk) in.oom = 1; else word_breaks(in.v, in.n, brk);
    }
    {
        int seen_cased = 0;     /* title: already cased a letter in this word */
        for (i = 0; i < in.n && !in.oom; i++) {
            uint32_t c = in.v[i];
            switch (op) {
                case OP_LOWER:
                    if (c < 0x80) { cp_push(&out, (c >= 'A' && c <= 'Z') ? c + 32 : c); break; }
                    if (c == 0x03A3) { cp_push(&out, final_sigma(in.v, in.n, i) ? 0x03C2 : 0x03C3); break; }
                    case_push(&out, CASE_TABLE(lower), c);
                    break;
                case OP_UPPER:
                    if (c < 0x80) { cp_push(&out, (c >= 'a' && c <= 'z') ? c - 32 : c); break; }
                    case_push(&out, CASE_TABLE(upper), c);
                    break;
                case OP_FOLD:
                    if (c < 0x80) { cp_push(&out, (c >= 'A' && c <= 'Z') ? c + 32 : c); break; }
                    case_push(&out, CASE_TABLE(fold), c);
                    break;
                default:   /* title */
                    if (brk[i]) seen_cased = 0;
                    if (!seen_cased && is_cased(c)) {
                        seen_cased = 1;
                        case_push(&out, CASE_TABLE(title), c);
                    } else if (!seen_cased && is_wordlike(c)) {
                        seen_cased = 1;    /* "3rd", not "3Rd": a leading digit starts the word */
                        cp_push(&out, c);
                    } else if (c == 0x03A3) {
                        cp_push(&out, final_sigma(in.v, in.n, i) ? 0x03C2 : 0x03C3);
                    } else {
                        case_push(&out, CASE_TABLE(lower), c);
                    }
                    break;
            }
        }
    }
    if (in.oom) out.oom = 1;
    r = res_bytes_from_cps(&out);
    free(in.v); free(out.v); free(brk);
    return r;
}

/* ── Grapheme clusters (UAX #29 §3.1.1, Unicode 16) ────────────────────── */

typedef struct { int ri_count; int emoji; int incb; } gstate;

/* Is there a break between prev (pr, already folded into st) and cur? */
static int grapheme_break(const uni_rec* pr, const uni_rec* cr, const gstate* st) {
    int p = pr->gcb, c = cr->gcb;
    if (p == GCB_CR && c == GCB_LF) return 0;                                  /* GB3 */
    if (p == GCB_Control || p == GCB_CR || p == GCB_LF) return 1;               /* GB4 */
    if (c == GCB_Control || c == GCB_CR || c == GCB_LF) return 1;               /* GB5 */
    if (p == GCB_L && (c == GCB_L || c == GCB_V || c == GCB_LV || c == GCB_LVT)) return 0; /* GB6 */
    if ((p == GCB_LV || p == GCB_V) && (c == GCB_V || c == GCB_T)) return 0;   /* GB7 */
    if ((p == GCB_LVT || p == GCB_T) && c == GCB_T) return 0;                  /* GB8 */
    if (c == GCB_Extend || c == GCB_ZWJ) return 0;                             /* GB9 */
    if (c == GCB_SpacingMark) return 0;                                        /* GB9a */
    if (p == GCB_Prepend) return 0;                                            /* GB9b */
    if (st->incb == 2 && uni_incb(cr) == INCB_CONSONANT) return 0;             /* GB9c */
    if (st->emoji == 2 && (cr->flags & F_EXTPICT)) return 0;                   /* GB11 */
    if (p == GCB_RI && c == GCB_RI && (st->ri_count & 1)) return 0;            /* GB12/13 */
    return 1;                                                                  /* GB999 */
}

static void gstate_push(gstate* st, const uni_rec* r) {
    int ib = uni_incb(r);
    if (r->gcb == GCB_RI) st->ri_count++; else st->ri_count = 0;
    if (r->flags & F_EXTPICT) st->emoji = 1;
    else if (r->gcb == GCB_Extend && st->emoji == 1) st->emoji = 1;
    else if (r->gcb == GCB_ZWJ && st->emoji == 1) st->emoji = 2;
    else st->emoji = 0;
    if (ib == INCB_CONSONANT) st->incb = 1;
    else if (ib == INCB_LINKER && st->incb >= 1) st->incb = 2;
    else if (ib == INCB_EXTEND && st->incb >= 1) { /* keep */ }
    else st->incb = 0;
}

/* Byte offset where the grapheme cluster starting at byte `pos` ends. */
static size_t grapheme_end(const unsigned char* s, size_t n, size_t pos) {
    gstate st = {0, 0, 0};
    size_t i = pos;
    const uni_rec* pr;
    if (pos >= n) return n;
    /* ASCII fast path: printable ASCII followed by ASCII (not CR) ends here */
    if (s[i] >= 0x20 && s[i] < 0x7F && (i + 1 >= n || (s[i + 1] < 0x80 && s[i + 1] != 0x0D))) return i + 1;
    pr = uni_rec_of(u8_next(s, n, &i));
    gstate_push(&st, pr);
    while (i < n) {
        size_t j = i;
        const uni_rec* cr = uni_rec_of(u8_next(s, n, &j));
        if (grapheme_break(pr, cr, &st)) break;
        gstate_push(&st, cr);
        pr = cr;
        i = j;
    }
    return i;
}

/* ── Word boundaries (UAX #29 §4.1.1, Unicode 16) ──────────────────────── */

static inline int wb_ign(int w) { return w == WB_Extend || w == WB_Format || w == WB_ZWJ; }
static inline int wb_ah(int w) { return w == WB_ALetter || w == WB_Hebrew_Letter; }
static inline int wb_midletq(int w) { return w == WB_MidLetter || w == WB_MidNumLet || w == WB_Single_Quote; }
static inline int wb_midnumq(int w) { return w == WB_MidNum || w == WB_MidNumLet || w == WB_Single_Quote; }
static inline int wb_nl(int w) { return w == WB_Newline || w == WB_CR || w == WB_LF; }

/* brk[i] = 1 when there is a word boundary before v[i] (brk[0] = brk[n] = 1). */
static void word_breaks(const uint32_t* v, size_t n, unsigned char* brk) {
    unsigned char* w = (unsigned char*)malloc(n + 1);
    unsigned char* xp = (unsigned char*)malloc(n + 1);   /* Extended_Pictographic */
    long* eff = (long*)malloc((n + 1) * sizeof(long));    /* index of effective char (WB4) */
    size_t i;
    if (!w || !xp || !eff) {    /* out of memory: every code point its own word */
        for (i = 0; i <= n; i++) brk[i] = 1;
        free(w); free(xp); free(eff);
        return;
    }
    for (i = 0; i < n; i++) { const uni_rec* r = uni_rec_of(v[i]); w[i] = r->wb; xp[i] = (r->flags & F_EXTPICT) != 0; }
    /* eff[i]: the char that v[i] belongs to after WB4 (itself, or the base it extends). */
    for (i = 0; i < n; i++) {
        if (wb_ign(w[i]) && i > 0 && !wb_nl(w[eff[i - 1]])) eff[i] = eff[i - 1];
        else eff[i] = (long)i;
    }
    brk[0] = 1;
    if (n > 0) brk[n] = 1;
    for (i = 1; i < n; i++) {
        int p = w[i - 1], c = w[i];
        long pj, pk, nj;
        int prev, prev2, next;
        if (p == WB_CR && c == WB_LF) { brk[i] = 0; continue; }                 /* WB3 */
        if (wb_nl(p)) { brk[i] = 1; continue; }                                  /* WB3a */
        if (wb_nl(c)) { brk[i] = 1; continue; }                                  /* WB3b */
        if (p == WB_ZWJ && xp[i]) { brk[i] = 0; continue; }                      /* WB3c */
        if (p == WB_WSegSpace && c == WB_WSegSpace) { brk[i] = 0; continue; }    /* WB3d */
        if (wb_ign(c)) { brk[i] = 0; continue; }                                 /* WB4 */
        pj = eff[i - 1];
        prev = w[pj];
        pk = pj > 0 ? eff[pj - 1] : -1;
        prev2 = pk >= 0 ? w[pk] : -1;
        nj = (long)i + 1;
        while (nj < (long)n && wb_ign(w[nj])) nj++;
        next = nj < (long)n ? w[nj] : -1;
        if (wb_ah(prev) && wb_ah(c)) { brk[i] = 0; continue; }                   /* WB5 */
        if (wb_ah(prev) && wb_midletq(c) && next >= 0 && wb_ah(next)) { brk[i] = 0; continue; }   /* WB6 */
        if (prev2 >= 0 && wb_ah(prev2) && wb_midletq(prev) && wb_ah(c)) { brk[i] = 0; continue; } /* WB7 */
        if (prev == WB_Hebrew_Letter && c == WB_Single_Quote) { brk[i] = 0; continue; }          /* WB7a */
        if (prev == WB_Hebrew_Letter && c == WB_Double_Quote && next == WB_Hebrew_Letter) { brk[i] = 0; continue; } /* WB7b */
        if (prev2 == WB_Hebrew_Letter && prev == WB_Double_Quote && c == WB_Hebrew_Letter) { brk[i] = 0; continue; } /* WB7c */
        if (prev == WB_Numeric && c == WB_Numeric) { brk[i] = 0; continue; }     /* WB8 */
        if (wb_ah(prev) && c == WB_Numeric) { brk[i] = 0; continue; }            /* WB9 */
        if (prev == WB_Numeric && wb_ah(c)) { brk[i] = 0; continue; }            /* WB10 */
        if (prev2 == WB_Numeric && wb_midnumq(prev) && c == WB_Numeric) { brk[i] = 0; continue; } /* WB11 */
        if (prev == WB_Numeric && wb_midnumq(c) && next == WB_Numeric) { brk[i] = 0; continue; }  /* WB12 */
        if (prev == WB_Katakana && c == WB_Katakana) { brk[i] = 0; continue; }   /* WB13 */
        if ((wb_ah(prev) || prev == WB_Numeric || prev == WB_Katakana || prev == WB_ExtendNumLet) &&
            c == WB_ExtendNumLet) { brk[i] = 0; continue; }                      /* WB13a */
        if (prev == WB_ExtendNumLet && (wb_ah(c) || c == WB_Numeric || c == WB_Katakana)) { brk[i] = 0; continue; } /* WB13b */
        if (prev == WB_RI && c == WB_RI) {                                       /* WB15/16 */
            long k = pj; int cnt = 0;
            while (k >= 0 && w[k] == WB_RI) { cnt++; k = k > 0 ? eff[k - 1] : -1; }
            if (cnt & 1) { brk[i] = 0; continue; }
        }
        brk[i] = 1;                                                              /* WB999 */
    }
    free(w); free(xp); free(eff);
}

/* ── Sentence boundaries (UAX #29 §5.1, Unicode 16) ────────────────────── */

static inline int sb_ign(int s) { return s == SB_Extend || s == SB_Format; }
static inline int sb_para(int s) { return s == SB_Sep || s == SB_CR || s == SB_LF; }
static inline int sb_saterm(int s) { return s == SB_STerm || s == SB_ATerm; }

static void sentence_breaks(const uint32_t* v, size_t n, unsigned char* brk) {
    unsigned char* t = (unsigned char*)malloc(n + 1);
    long* eff = (long*)malloc((n + 1) * sizeof(long));
    size_t i;
    if (!t || !eff) {
        for (i = 0; i <= n; i++) brk[i] = 1;
        free(t); free(eff);
        return;
    }
    for (i = 0; i < n; i++) t[i] = uni_rec_of(v[i])->sb;
    for (i = 0; i < n; i++) {
        if (sb_ign(t[i]) && i > 0 && !sb_para(t[eff[i - 1]])) eff[i] = eff[i - 1];
        else eff[i] = (long)i;
    }
    brk[0] = 1;
    if (n > 0) brk[n] = 1;
    for (i = 1; i < n; i++) {
        int p = t[i - 1], c = t[i];
        long pj, k;
        int prev, sawsp = 0, term = -1;
        if (p == SB_CR && c == SB_LF) { brk[i] = 0; continue; }     /* SB3 */
        if (sb_para(p)) { brk[i] = 1; continue; }                   /* SB4 */
        if (sb_ign(c)) { brk[i] = 0; continue; }                    /* SB5 */
        pj = eff[i - 1];
        prev = t[pj];
        if (prev == SB_ATerm && c == SB_Numeric) { brk[i] = 0; continue; }       /* SB6 */
        if (prev == SB_ATerm && c == SB_Upper && pj > 0) {                       /* SB7 */
            int p2 = t[eff[pj - 1]];
            if (p2 == SB_Upper || p2 == SB_Lower) { brk[i] = 0; continue; }
        }
        /* Match SATerm Close* Sp* backwards from the effective previous char. */
        k = pj;
        while (k >= 0 && t[k] == SB_Sp) { sawsp = 1; k = k > 0 ? eff[k - 1] : -1; }
        while (k >= 0 && t[k] == SB_Close) { k = k > 0 ? eff[k - 1] : -1; }
        if (k >= 0 && sb_saterm(t[k])) term = t[k];
        if (term < 0) { brk[i] = 0; continue; }                     /* SB998 */
        if (term == SB_ATerm) {                                     /* SB8 */
            size_t m = i;
            while (m < n) {
                int x = t[m];
                if (x == SB_OLetter || x == SB_Upper || x == SB_Lower || sb_para(x) || sb_saterm(x)) break;
                m++;
            }
            if (m < n && t[m] == SB_Lower) { brk[i] = 0; continue; }
        }
        if (c == SB_SContinue || sb_saterm(c)) { brk[i] = 0; continue; }         /* SB8a */
        if (!sawsp && (c == SB_Close || c == SB_Sp || sb_para(c))) { brk[i] = 0; continue; } /* SB9 */
        if (c == SB_Sp || sb_para(c)) { brk[i] = 0; continue; }                 /* SB10 */
        brk[i] = 1;                                                              /* SB11 */
    }
    free(t); free(eff);
}

/* ── Segmentation results ──────────────────────────────────────────────── */

enum { SEG_GRAPHEME = 0, SEG_WORD = 1, SEG_WORD_ONLY = 2, SEG_SENTENCE = 3 };

static int pairs_push(uni_result* r, size_t* cap, int64_t a, int64_t b) {
    if (r->count == *cap) {
        size_t nc = *cap ? *cap * 2 : 64;
        int64_t* np = (int64_t*)realloc(r->pairs, nc * 2 * sizeof(int64_t));
        if (!np) return 0;
        r->pairs = np; *cap = nc;
    }
    r->pairs[2 * r->count] = a;
    r->pairs[2 * r->count + 1] = b;
    r->count++;
    return 1;
}

static int is_wordlike(uint32_t c) {
    int g = uni_rec_of(c)->gc;
    return (g >= GC_Lu && g <= GC_Lo) || (g >= GC_Nd && g <= GC_No);
}

static uni_result* segment(int kind, const unsigned char* s, size_t n) {
    uni_result* r = (uni_result*)calloc(1, sizeof *r);
    size_t cap = 0;
    if (!r) return NULL;
    if (kind == SEG_GRAPHEME) {
        size_t pos = 0;
        while (pos < n) {
            size_t e = grapheme_end(s, n, pos);
            if (!pairs_push(r, &cap, (int64_t)pos, (int64_t)e)) goto oom;
            pos = e;
        }
        return r;
    } else {
        cpbuf b = {0};
        size_t* off;
        unsigned char* brk;
        size_t i = 0, k = 0, start;
        cp_reserve(&b, n + 1);
        off = (size_t*)malloc((n + 1) * sizeof(size_t));
        brk = (unsigned char*)calloc(n + 1, 1);
        if (b.oom || !off || !brk) { free(b.v); free(off); free(brk); goto oom; }
        while (i < n) { off[b.n] = i; b.v[b.n++] = u8_next(s, n, &i); }
        off[b.n] = n;
        if (kind == SEG_SENTENCE) sentence_breaks(b.v, b.n, brk);
        else word_breaks(b.v, b.n, brk);
        start = 0;
        for (k = 1; k <= b.n; k++) {
            if (!brk[k]) continue;
            if (kind == SEG_WORD_ONLY) {
                size_t m; int keep = 0;
                for (m = start; m < k && !keep; m++) keep = is_wordlike(b.v[m]);
                if (!keep) { start = k; continue; }
            }
            if (!pairs_push(r, &cap, (int64_t)off[start], (int64_t)off[k])) { free(b.v); free(off); free(brk); goto oom; }
            start = k;
        }
        free(b.v); free(off); free(brk);
        return r;
    }
oom:
    free(r->pairs); free(r);
    return NULL;
}

/* ── Display width ─────────────────────────────────────────────────────── */

static int64_t cluster_width(const unsigned char* s, size_t a, size_t b) {
    size_t i = a;
    int w = -1, ri = 0, emoji_base = 0;
    while (i < b) {
        uint32_t cp = u8_next(s, b, &i);
        const uni_rec* r = uni_rec_of(cp);
        if (cp == 0xFE0F && emoji_base) return 2;     /* emoji presentation selector */
        if (w < 0 && r->width > 0) {
            w = r->width;
            emoji_base = (r->flags & F_EXTPICT) != 0 || (cp >= '#' && cp <= '9');
        }
        if (r->gcb == GCB_RI) ri++;
    }
    if (ri >= 2) return 2;
    return w < 0 ? 0 : w;
}

/* ── Exported API ──────────────────────────────────────────────────────── */

/* Writes the UCD version ("16.0.0") NUL-terminated into dst (>= 16 bytes). */
int64_t trc_uni_version(char* dst) {
    size_t n = strlen(UNI_VERSION);
    memcpy(dst, UNI_VERSION, n + 1);
    return (int64_t)n;
}

/* 0 = yes, 1 = no, 2 = maybe (forms: 0 NFC, 1 NFD, 2 NFKC, 3 NFKD). */
int64_t trc_uni_quick_check(int64_t form, const char* s, int64_t n) {
    return quick_check((int)form, (const unsigned char*)s, (size_t)n);
}

/* op 0-3: NFC/NFD/NFKC/NFKD, 4 lower, 5 upper, 6 casefold, 7 title.
 * Returns a result handle (0 when out of memory). */
int64_t trc_uni_transform(int64_t op, const char* s, int64_t n) {
    if (op >= 0 && op <= 3) return (int64_t)(intptr_t)normalize((int)op, (const unsigned char*)s, (size_t)n);
    return (int64_t)(intptr_t)case_map((int)op, (const unsigned char*)s, (size_t)n);
}

/* kind 0 graphemes, 1 word segments, 2 words only, 3 sentences. */
int64_t trc_uni_segment(int64_t kind, const char* s, int64_t n) {
    return (int64_t)(intptr_t)segment((int)kind, (const unsigned char*)s, (size_t)n);
}

#define H(h) ((uni_result*)(intptr_t)(h))
int64_t trc_uni_buf_len(int64_t h) { return h ? (int64_t)H(h)->len : 0; }

/* Copy a byte result into dst (len bytes + NUL) and free the handle. */
void trc_uni_buf_take(int64_t h, char* dst) {
    uni_result* r = H(h);
    if (!r) return;
    memcpy(dst, r->bytes, r->len);
    dst[r->len] = 0;
    free(r->bytes); free(r->pairs); free(r);
}

int64_t trc_uni_seg_count(int64_t h) { return h ? (int64_t)H(h)->count : 0; }
int64_t trc_uni_seg_start(int64_t h, int64_t i) { return H(h)->pairs[2 * i]; }
int64_t trc_uni_seg_end(int64_t h, int64_t i) { return H(h)->pairs[2 * i + 1]; }
void trc_uni_free(int64_t h) {
    uni_result* r = H(h);
    if (!r) return;
    free(r->bytes); free(r->pairs); free(r);
}

/* Copy s[a, a+len) to dst and NUL-terminate. */
void trc_uni_copy(const char* s, int64_t a, int64_t len, char* dst) {
    memcpy(dst, s + a, (size_t)len);
    dst[len] = 0;
}

int64_t trc_uni_grapheme_count(const char* s, int64_t n) {
    size_t pos = 0, cnt = 0;
    while (pos < (size_t)n) { pos = grapheme_end((const unsigned char*)s, (size_t)n, pos); cnt++; }
    return (int64_t)cnt;
}

/* Byte offset of the end of the grapheme cluster that starts at `pos`. */
int64_t trc_uni_grapheme_end(const char* s, int64_t n, int64_t pos) {
    return (int64_t)grapheme_end((const unsigned char*)s, (size_t)n, (size_t)pos);
}

int64_t trc_uni_width(const char* s, int64_t n) {
    const unsigned char* u = (const unsigned char*)s;
    size_t pos = 0;
    int64_t w = 0;
    while (pos < (size_t)n) {
        size_t e = grapheme_end(u, (size_t)n, pos);
        if (e == pos + 1 && u[pos] >= 0x20 && u[pos] < 0x7F) w += 1;
        else w += cluster_width(u, pos, e);
        pos = e;
    }
    return w;
}

/* Number of bytes of the longest prefix of whole grapheme clusters whose
 * display width is at most max_width. */
int64_t trc_uni_width_prefix(const char* s, int64_t n, int64_t max_width) {
    const unsigned char* u = (const unsigned char*)s;
    size_t pos = 0;
    int64_t w = 0;
    while (pos < (size_t)n) {
        size_t e = grapheme_end(u, (size_t)n, pos);
        int64_t cw = cluster_width(u, pos, e);
        if (w + cw > max_width) break;
        w += cw;
        pos = e;
    }
    return (int64_t)pos;
}

/* Per-code-point properties. */
int64_t trc_uni_char_width(int64_t cp) {
    if (cp < 0 || cp >= 0x110000) return 0;
    return uni_rec_of((uint32_t)cp)->width;
}
int64_t trc_uni_ccc(int64_t cp) {
    if (cp < 0 || cp >= 0x110000) return 0;
    return uni_rec_of((uint32_t)cp)->ccc;
}
int64_t trc_uni_gc(int64_t cp) {
    if (cp < 0 || cp >= 0x110000) return GC_Cn;
    return uni_rec_of((uint32_t)cp)->gc;
}
/* which: 0 lower, 1 upper, 2 title, 3 fold (simple, single code point mappings). */
int64_t trc_uni_simple_case(int64_t which, int64_t cp) {
    if (cp < 0 || cp >= 0x110000) return cp;
    switch (which) {
        case 0: return case_simple(CASE_TABLE(lower), (uint32_t)cp);
        case 1: return case_simple(CASE_TABLE(upper), (uint32_t)cp);
        case 2: return case_simple(CASE_TABLE(title), (uint32_t)cp);
        default: return case_simple(CASE_TABLE(fold), (uint32_t)cp);
    }
}
/* UTF-8 encode one code point into dst (>= 5 bytes); returns the byte count. */
int64_t trc_uni_encode(int64_t cp, char* dst) {
    unsigned char* q;
    if (cp < 0 || cp >= 0x110000 || (cp >= 0xD800 && cp <= 0xDFFF)) cp = 0xFFFD;
    q = u8_put((unsigned char*)dst, (uint32_t)cp);
    *q = 0;
    return (int64_t)(q - (unsigned char*)dst);
}
